var props = ["id", "name", "authors", "cover", "types", "last_update_chapter_name"],
	regs = props.map(function(prop){
			return new RegExp("\""+prop+"\":(\"[^\"]+\")");
		}),
	json = [],
	obj,
	match;
java.getString("@JSon:$",false).match(/{[^}]+}/g).forEach(function(comic){
	obj = {}
	props.forEach(function(prop,i){
		match = comic.match(regs[i]);
		obj[prop] = JSON.parse(match&&match[1]);
	});
	json.push(obj)
});
